    'repository.postgres_mcp_server.mcp_server_uzhe_est' => 'MCP-сервер «%s» уже есть.',
    'repository.postgres_project.proekt_uzhe_est' => 'Проект «%s» уже есть.',
    'repository.postgres_secret.sekret_uzhe_est' => 'Секрет «%s» уже есть.',
